  "example": "（来源：题库 f12）短周期元素 X、Y、Z：X 原子最外层电子数是内层电子数的 2 倍；Y 与 X 同周期，其最高正价与最低负价的绝对值之差为 2；Z 的阴离子与 Ne 原子电子层结构相同，且带 1 个单位负电荷。（a）X 的元素符号；（b）Y 的元素符号；（c）Z 的元素符号。\n第 1 步：X——层间倍数关系（电子排布类）；Y——“与 X 同周期”（位置关系类）＋“正负价绝对值之差为 2”（化合价类）；Z——“阴离子与 Ne 同电子层结构、带 1 个单位负电荷”（离子结构类）。\n第 2 步：X 给出层间倍数关系，先解 X，进入第 3 步。\n第 3 步：X 的内层只有 K 层，内层电子数 = 2 个。\n第 4 步：最外层电子数 = 2 × 2 = 4 个，排布式为 2、4。\n第 5 步：2 + 4 = 6，核外电子总数 6 个。\n第 6 步：原子序数 6，（a）X = C，进入第 15 步。\n第 15 步：C 与其他条件无冲突，本轮结束。\n（处理 Y，回到第 2 步）第 2 步：Y 没有排布或倍数关系，进入第 7 步。\n第 7 步：Y 没有给离子电子层结构，进入第 10 步。\n第 10 步：Y 给了化合价（差值 2），进入第 11 步。\n第 11 步：给的是“正负价绝对值之差”，进入第 13 步。\n第 13 步：最外层电子数 =（2 + 8）÷ 2 = 5 个，进入第 14 步。\n第 14 步：Y 与 X（C，第二周期）同周期，故 Y 在第二周期；第二周期最外层 5 个电子的是 N，（b）Y = N。\n第 15 步：若漏掉“同周期”，同一组化合价还会指向第三周期的 P，此限制正是用来排除 P 的；取 N 不冲突，进入第 16 步。\n（处理 Z，回到第 2 步）第 2 步：Z 没有排布或倍数关系，进入第 7 步。\n第 7 步：Z 给了离子电子层结构，进入第 8 步。\n第 8 步：Z 的阴离子与 Ne 同结构，即 10 个电子；原子核外电子数 = 10 − 1 = 9 个。\n第 9 步：原子序数 9，（c）Z = F（排布 2、7，与题意一致），进入第 15 步。\n第 15 步：F 与其他条件无冲突，进入第 16 步。\n第 16 步：代回题干——X = C、Y = N、Z = F；“Y 与 X 同周期”成立（均为第二周期），三元素位置关系与化合价结论均无矛盾。",
