    "text": "对同种元素的几种微粒，按“阴离子 ＞ 原子 ＞ 阳离子”修正顺序。",
    "warns": [
     "同种元素的不同价态阳离子，电荷越高半径越小，如 Fe³⁺＜Fe²⁺；得电子层数不变、电子增多则半径变大，失电子若少了一层则半径明显变小。"
    ]
