  "example": "某酸性废水样品 pH=2，呈无色。下列各组离子在该废水中能大量共存的是？A. Fe²⁺、Na⁺、NO₃⁻、Cl⁻；B. Ba²⁺、Na⁺、SO₄²⁻、Cl⁻；C. K⁺、HCO₃⁻、Na⁺、Cl⁻；D. Na⁺、K⁺、SO₄²⁻、NO₃⁻。（来源：题库 c01）\n按步骤 1–2：pH=2 为酸性，C 中 HCO₃⁻ 与 H⁺ 反应放 CO₂，排除。\n按步骤 3：B 中 Ba²⁺ 与 SO₄²⁻ 生成 BaSO₄ 沉淀，排除。\n按步骤 6：A 中酸性条件下 NO₃⁻ 会把 Fe²⁺ 氧化为 Fe³⁺，排除。\n按步骤 7–8：D 无有色离子且无反应，选 D。",
