  "example": "反应 3Cl₂+8NH₃→6NH₄Cl+N₂ 中，被氧化的 NH₃ 与被还原的 Cl₂ 的物质的量之比是？A. 3∶2；B. 2∶3；C. 1∶3；D. 3∶1。（来源：题库 s15）\n按步骤 1–2：8 mol NH₃ 中只有 2 mol 被氧化为 N₂（N 由 −3 升至 0，共失 6 mol 电子），其余 6 mol 只与 HCl 结合成 NH₄Cl。\n按步骤 3–4：3 mol Cl₂ 全部被还原（共得 6 mol 电子）。\n按步骤 5：失 6 mol 电子与得 6 mol 电子相等。\n按步骤 6–7：比值为 2∶3，选 B。",
