  "example": "配制 250 mL 0.100 mol/L NaCl 溶液，下列仪器选择与使用正确的是 A. 用 250 mL 量筒量取 250 mL 蒸馏水加入固体中溶解定容 B. 用托盘天平称取 NaCl 1.46 g（M = 58.5 g/mol，理论值 1.4625 g） C. 用 250 mL 容量瓶定容，定容前检查容量瓶是否漏水 D. 溶解 NaCl 时直接在容量瓶中加水搅拌\n按步骤 2：A 项量筒不能作定容容器，配制体积应以容量瓶刻度为准，错误。\n按步骤 3：B 项托盘天平精确到 0.1 g，称不出 1.46 g，应称 1.5 g，错误。\n按步骤 4–5：C 项配制一定浓度溶液必须用容量瓶定容，容量瓶使用前要检漏；正确。\n按步骤 4：D 项容量瓶不能直接溶解固体，错误。\n选 C。",
