  "example": "（2021 全国乙卷 28 题(4)）NOCl 在光照下分解的机理为：① NOCl + hν → NOCl*；② NOCl + NOCl* → 2NO + Cl₂。分解 1 mol NOCl 需要吸收多少 mol 光子？\n步骤 1：机理共两步：① NOCl + hν → NOCl*；② NOCl + NOCl* → 2NO + Cl₂。\n步骤 2：NOCl* 在第①步生成、在第②步被消耗，是中间体。\n步骤 3：没有物质在某步被消耗又在另一步生成，本题无催化剂。\n步骤 4：NOCl* 在①②两步中的计量数都是 1，已相等。\n步骤 5：计量数相等，不做乘法。\n步骤 6：①+②相加，消去两边的 NOCl*，得总反应式 2NOCl + hν → 2NO + Cl₂。\n步骤 7：hν 只在第①步反应物中出现，保留在总反应式反应物一侧。\n步骤 8：验算原子守恒：左边 N 2、O 2、Cl 2；右边 N 2、O 2、Cl 2，两边相等。\n步骤 9：题目问“分解 1 mol NOCl 需要吸收多少 mol 光子”，是计量计算，转步骤 10。\n步骤 10：按总反应式 2NOCl + hν → 2NO + Cl₂，n(hν) = 1 mol × 1 / 2 = 0.5 mol。\n步骤 11：答案 0.5 mol；数值小于 1 mol NOCl 的物质的量，与“2 mol NOCl 对应 1 mol 光子”的比例一致。",
