  "example": "高钛炉渣“焙烧”过程中，Al₂O₃ 转化为 NH₄Al(SO₄)₂，同时生成 NH₃ 与 H₂O。写出该反应的化学方程式。\n步骤 1：反应物为 Al₂O₃ 与 (NH₄)₂SO₄（题干给出焙烧时加入 (NH₄)₂SO₄），生成物为 NH₄Al(SO₄)₂、NH₃、H₂O。\n步骤 2：反应物与生成物均已完整给出，无需补全。\n步骤 3：骨架式为 Al₂O₃ + (NH₄)₂SO₄ → NH₄Al(SO₄)₂ + NH₃ + H₂O。\n步骤 4：核对化合价：Al 反应前后均为 +3 价，N 均为 −3 价，S 均为 +6 价，H、O 的化合价也均未变化，无升降，不是氧化还原反应。\n步骤 5：无化合价升降，不转 02-SOP-12，继续用本 SOP。\n步骤 6：选用待定系数法，设 Al₂O₃ 的系数为 1。\n步骤 7：由 Al 守恒：左侧 Al 为 2，NH₄Al(SO₄)₂ 的系数为 2；由 S 守恒：右侧 S 为 2×2 = 4，(NH₄)₂SO₄ 的系数为 4；由 N 守恒：左侧 N 为 4×2 = 8，右侧 NH₄Al(SO₄)₂ 中 N 为 2，剩余 6 个 N 归 NH₃，NH₃ 的系数为 6；由 H 守恒：左侧 H 为 4×8 = 32，右侧 NH₄Al(SO₄)₂ 中 H 为 2×4 = 8，NH₃ 中 H 为 6×3 = 18，剩余 6 个 H 归 H₂O，H₂O 的系数为 3。复盐 NH₄Al(SO₄)₂ 全程按整体处理，未拆开配平。\n步骤 8：配平后的方程式为 Al₂O₃ + 4(NH₄)₂SO₄ = 2NH₄Al(SO₄)₂ + 6NH₃ + 3H₂O。\n步骤 9：逐元素复核：Al 左 2 右 2，N 左 8 右 8，H 左 32 右 32，S 左 4 右 4，O 左 3+16 = 19，右 16+3 = 19，全部相等。\n步骤 10：题干条件为“焙烧”，标注在等号上方。\n步骤 11：焙烧高温下 NH₃ 与 H₂O 均为气体，均标 ↑。\n步骤 12：系数 1、4、2、6、3 已为最简整数比。完整方程式：Al₂O₃ + 4(NH₄)₂SO₄ =（焙烧） 2NH₄Al(SO₄)₂ + 6NH₃↑ + 3H₂O↑。",
