  "example": "2021 年全国乙卷第 26 题（6）：将“母液①”和“母液②”混合，吸收尾气，经处理得___，循环利用。\n步骤 1：问题所指的流股是“母液①”“母液②”与“尾气”，三者在流程末端汇合。\n步骤 2：流程开头是高钛炉渣与 (NH₄)₂SO₄ 焙烧；焙烧后水浸、分步沉淀得到母液①；水浸渣酸溶、TiO²⁺ 水解析出 TiO₂·xH₂O 后得到母液②。\n步骤 3：母液①由分步沉淀产生；母液②由 TiO²⁺ 水解产生；尾气由焙烧产生。\n步骤 4：母液①含 (NH₄)₂SO₄ 与少量 CaSO₄；母液②含 TiO²⁺ 水解产生的 H₂SO₄。\n步骤 5–6：尾气是焙烧放出的 NH₃，NH₃ 与母液②中的 H₂SO₄ 能发生反应：2NH₃ + H₂SO₄ = (NH₄)₂SO₄。\n步骤 8：产物 (NH₄)₂SO₄ 正是流程开头焙烧步骤的原料。\n步骤 9–10：(NH₄)₂SO₄ 在本流程中产生（尾气吸收），又在本流程中消耗（焙烧原料），两个条件都满足，是循环利用的物质。\n步骤 12：答案为 (NH₄)₂SO₄。",
