  "example": "2021 年全国乙卷 Q10(1)：历史上海藻提碘中得到一种红棕色液体，由于性质相似，Liebig 误认为是 ICl，从而错过了一种新元素的发现，该元素是 ___。\n步骤 1：题干给出的颜色、状态线索是“红棕色液体”。\n步骤 2：题干还给出其他线索：海藻提碘的史实背景；该液体与 ICl 性质相似；Liebig 误认它为 ICl。\n步骤 3：按颜色状态对照卤素单质表，红棕色液体初步锁定为 Br₂。\n步骤 5：用其他线索验证——Br₂ 是常温下唯一的液态非金属单质，与“红棕色液体”相符；Br₂ 与 ICl 颜色相同、性质相似，Liebig 误认合理；题干问的是“新元素”，ICl 是化合物不是单质，排除。\n步骤 6：本题只要求判断是哪种元素，不要求鉴别，跳过第 7–9 步。\n步骤 10–11：初步锁定与验证一致，答案：溴（Br）。",
