  "example": "AlCr₂ 具有体心四方结构，晶胞图顶角位置是 Al 原子。设 Cr 和 Al 原子半径分别为 r(Cr) 和 r(Al)，则金属原子空间占有率为 ___%（列出计算表达式）。\n步骤 1：体心四方结构，晶胞参数为 a、c。\n步骤 2：题目要求算空间占有率，需先数原子个数再算体积比。\n步骤 3：顶角 Al 共 8 个，8×1/8 = 1 个。\n步骤 5：体内还有 1 个 Al，计 1 个。\n步骤 6：Al 共 1 + 1 = 2 个；Cr 共 4 个。\n步骤 8：V(原子) = 2×(4/3)πr³(Al) + 4×(4/3)πr³(Cr) = (8/3)π(r³(Al) + 2r³(Cr))。\n步骤 9：四方晶胞，V(晶胞) = a²c。\n步骤 10：空间占有率 = (8/3)π(r³(Al) + 2r³(Cr)) / a²c × 100% = 8π(2r³(Cr)+r³(Al))/(3a²c)×100。\n步骤 11：原子个数 2 个 Al、4 个 Cr，半径已立方，晶胞体积为 a²c，百分号已写，检查无误。\n答案：顶角是 Al 原子；空间占有率 8π(2r³(Cr)+r³(Al))/(3a²c)×100。",
