  "example": "（2025 全国新课标卷 13 题）HF 总浓度 c总(HF)=0.1000 mol·L⁻¹ 的水溶液中存在平衡 HF⇌H⁺+F⁻、HF+F⁻⇌HF₂⁻，c(HF)、c(HF₂⁻)、c(F⁻)与 pH 的关系如图所示；pH=4 时 M 上标注点为 (4, 0.0110)、N 上为 (4, 0.0800)、P 上为 (4, 0.0045)。下列叙述正确的是____（B 项：K₁=c(H⁺)c(F⁻)/c(HF)≈7×10⁻⁴，K₂=c(HF₂⁻)/[c(HF)c(F⁻)]≈5）。\n步骤 1：溶液中存在电离平衡 HF⇌H⁺+F⁻ 与结合平衡 HF+F⁻⇌HF₂⁻，总浓度 c总(HF)=0.1000 mol·L⁻¹。\n步骤 2：M 随 pH 增大递减，为 c(HF)曲线；N 随 pH 增大递增，为 c(F⁻)曲线；P 先增后减呈小峰，为 c(HF₂⁻)曲线。A 项说 N 为 c(HF₂⁻)曲线，错误。\n步骤 3：pH=4 时 c(HF)+c(F⁻)+2c(HF₂⁻)=0.0110+0.0800+2×0.0045=0.1000 mol·L⁻¹，等于总浓度，归属正确。\n步骤 4：pH=4，c(H⁺)=10⁻⁴ mol·L⁻¹；c(HF)=0.0110、c(F⁻)=0.0800、c(HF₂⁻)=0.0045 mol·L⁻¹。\n步骤 5：K₁=c(H⁺)c(F⁻)/c(HF)，K₂=c(HF₂⁻)/[c(HF)c(F⁻)]。\n步骤 6：K₁=10⁻⁴×0.0800/0.0110≈7.3×10⁻⁴，K₂=0.0045/(0.0110×0.0800)≈5.1，与 B 项的数量级一致，B 正确。\n步骤 7：物料守恒应为 c总(HF)=c(HF)+c(F⁻)+2c(HF₂⁻)，C 项缺系数 2，错误。\n步骤 8：电荷守恒须列出溶液中全部离子：c(H⁺)=c(F⁻)+c(HF₂⁻)+c(OH⁻)+c(外来阴离子)。\n步骤 9：0.1000 mol·L⁻¹ 纯 HF 溶液的 pH 约为 2.1，达不到 pH=1；pH=1 须外加强酸，引入外来阴离子，D 项的电荷守恒式漏项，错误。\n步骤 10：图中 pH=1 时 c(F⁻)+c(HF₂⁻)≈0.0015 mol·L⁻¹，远小于 c(H⁺)=0.1 mol·L⁻¹，D 项两边数量级不符。\n步骤 11：只有 B 正确，答案为 B。",
