  "example": "（2025 全国新课标卷 27 题(2)）蛇纹石（主要成分 Mg₃Si₂O₅(OH)₄，伴生少量 Ni、Fe、Al）与绿矾耦合回收 NiO 并矿化固定 CO₂。经“焙烧①”“水浸”，过滤分离后，滤液中金属离子的浓度（mol·L⁻¹）分别为：Ni²⁺ 0.005、Fe³⁺ 0.150、Mg²⁺ 0.430、Al³⁺ 0.010。滤渣①的主要成分是____、____。\n步骤 1：原料成分：蛇纹石 Mg₃Si₂O₅(OH)₄（伴生 Ni、Fe、Al）与绿矾 FeSO₄·7H₂O。\n步骤 2：焙烧①中绿矾分解：2FeSO₄·7H₂O=Fe₂O₃+SO₂↑+SO₃↑+14H₂O↑（高温）；SO₃ 遇水成 H₂SO₄，浸取蛇纹石。\n步骤 3：酸浸时 Mg、Ni、Al 进入溶液，SiO₂ 不溶。\n步骤 4：SiO₂ 不溶于稀硫酸，留在滤渣①中；Mg、Ni、Al 的氧化物与硅酸盐溶于酸进入溶液。\n步骤 5：滤液中 Fe³⁺ 浓度为 0.150 mol·L⁻¹，说明 Fe₂O₃ 部分溶于酸，剩余部分留在滤渣①中。\n步骤 6：滤渣①的主要成分：SiO₂、Fe₂O₃。\n步骤 7：滤液离子：Ni²⁺、Fe³⁺、Mg²⁺、Al³⁺，与题干给出的浓度一致。\n步骤 8：Mg、Ni、Al、Fe、Si 五种元素均有去向，无遗漏、无多出。\n步骤 9：本题只问滤渣①，不问后续步骤，跳过第 10、11 步。\n步骤 10：跳过（本题不涉及调 pH 沉淀）。\n步骤 11：跳过（本题不涉及后续沉淀剂或气体）。\n步骤 12：答案：SiO₂、Fe₂O₃。",
