  "example": "（2025 全国新课标卷 27 题(5)）调节“沉镍”后的溶液为碱性，通入 CO₂ 进行“矿化”，生成 Mg₅(CO₃)₄(OH)₂·4H₂O 沉淀。写出“矿化”反应的离子方程式。\n步骤 1：反应物：Mg²⁺、CO₂、OH⁻（碱性溶液）。\n步骤 2：生成物：Mg₅(CO₃)₄(OH)₂·4H₂O↓。\n步骤 3：碱性环境，反应物中有 OH⁻，无 H⁺。\n步骤 4：骨架式：Mg²⁺+CO₂+OH⁻→Mg₅(CO₃)₄(OH)₂·4H₂O↓。\n步骤 5：Mg²⁺、OH⁻ 拆成离子；CO₂ 为气体保留分子式；产物为沉淀保留化学式。\n步骤 6：产物为沉淀，标 ↓。\n步骤 7：配平：产物含 5 个 Mg，Mg²⁺ 系数为 5；产物含 4 个 C，CO₂ 系数为 4；产物 H 共 2+8=10 个，OH⁻ 系数为 10；验算 O：左 4×2+10=18，右 4×3+2+4=18，相等。\n步骤 8：电荷验算：左 5×(+2)+10×(−1)=0，右 0，相等。\n步骤 9：逐元素复核：Mg 5=5，C 4=4，H 10=10，O 18=18，全部相等。\n步骤 10：系数 5、4、10 无公约数，已为最简整数比。\n步骤 11：产物为难溶物，保留化学式，正确。\n步骤 12：答案：5Mg²⁺+4CO₂+10OH⁻=Mg₅(CO₃)₄(OH)₂·4H₂O↓。",
