  "example": "（2025 全国新课标卷 28 题(1)）乙酸、乙醇和乙酸乙酯的燃烧热分别为 −874 kJ·mol⁻¹、−1367 kJ·mol⁻¹ 和 −2238 kJ·mol⁻¹，则酯化反应 CH₃COOH(l)+C₂H₅OH(l)=CH₃COOC₂H₅(l)+H₂O(l) 的 ΔH=____kJ·mol⁻¹。\n步骤 1：目标反应：CH₃COOH(l)+C₂H₅OH(l)=CH₃COOC₂H₅(l)+H₂O(l)，求 ΔH。\n步骤 2：已知 ΔH：乙酸燃烧 −874、乙醇燃烧 −1367、乙酸乙酯燃烧 −2238 kJ·mol⁻¹。\n步骤 3：三个已知反应均为燃烧反应，ΔH 均为负值。\n步骤 4：燃烧方程式：① CH₃COOH+2O₂→2CO₂+2H₂O；② C₂H₅OH+3O₂→2CO₂+3H₂O；③ CH₃COOC₂H₅+5O₂→4CO₂+4H₂O；H₂O(l) 的燃烧热为 0。\n步骤 5：目标反应 = ①+②−③：左边 CH₃COOH+C₂H₅OH+5O₂+4CO₂+4H₂O，右边 4CO₂+5H₂O+CH₃COOC₂H₅+5O₂，约去相同项后即为目标反应。\n步骤 6：反应③逆向使用，系数为 −1。\n步骤 7：ΔH=ΔH①+ΔH②−ΔH③。\n步骤 8：ΔH=(−874)+(−1367)−(−2238)=−3 kJ·mol⁻¹。\n步骤 9：−3 kJ·mol⁻¹ 数量级很小，符合酯化反应热效应小的特点。\n步骤 10：答案：ΔH=−3 kJ·mol⁻¹。\n步骤 11：ΔH<0，酯化反应为放热反应，符号合理。",
