  "example": "（2025 全国新课标卷 29 题(1)）合成路线：A（C₁₃H₁₁NO₄）—①Fe 粉/盐酸→ B（苯环上含 PhO、H₂N、OCH₃；H₂N 与 PhO 邻位，OCH₃ 与 PhO 对位）。A 的结构简式是____。\n步骤 1：路线：A —①Fe 粉/盐酸→ B —②甲磺酰氯/吡啶→ C……目标：A 的结构。\n步骤 2：已知：A 的分子式为 C₁₃H₁₁NO₄；B 的结构已知（PhO、H₂N、OCH₃）。\n步骤 3：以 B 的结构为基准推 A。\n步骤 4：反应①的试剂为 Fe 粉/盐酸，是硝基还原为氨基的反应，故 A 中的 —NO₂ 在反应①中变为 B 中的 —NH₂。\n步骤 5：官能团变化：—NO₂→—NH₂；分子式变化：A 比 B 多 2 个 O、少 2 个 H。\n步骤 6：验算：A=C₁₃H₁₁NO₄，B=C₁₃H₁₃NO₂，A−B 为 −2H、+2O，与第 5 步一致。\n步骤 7：取代位置不变：B 中 H₂N 与 PhO 邻位、OCH₃ 与 PhO 对位，故 A 中 NO₂ 与 PhO 邻位、OCH₃ 与 PhO 对位。\n步骤 8：A 的结构：苯环上 1 位为 —OPh、2 位为 —NO₂、4 位为 —OCH₃。\n步骤 9：数原子数：C 6+6+1=13，H 3+5+3=11，N 1，O 1+2+1=4，即 C₁₃H₁₁NO₄，与题干分子式一致。\n步骤 10：A 的硝基可被 Fe/盐酸还原为氨基，与反应①相符。\n步骤 11：最终产物 F 为 6-苯氧基-7-甲磺酰氨基色酮，苯氧基与氨基的邻位关系与 A 的结构一致。\n步骤 12：答案：2-硝基-4-甲氧基苯基苯醚（苯环上 1 位 —OPh、2 位 —NO₂、4 位 —OCH₃）。",
