  "example": "（2025 全国新课标卷 29 题(7)）参照反应①（Fe 粉/盐酸还原硝基）和反应②（氨基与酰氯的取代反应，吡啶作碱），利用 1,2-二乙氧基苯和氯甲酸异丙酯完成杀菌剂乙霉威的合成路线。\n步骤 1：原料：1,2-二乙氧基苯（苯环上两个 —OC₂H₅，无其他基团）；目标产物乙霉威：苯环上两个 —OC₂H₅ 与一个 —NH—COO—CH(CH₃)₂（氨基甲酸酯基）。\n步骤 2：参照反应①：—NO₂ —Fe 粉/盐酸→ —NH₂；参照反应②：—NH₂ 与酰氯（R—COCl）—吡啶→ —NH—CO—R（取代反应，吡啶吸收 HCl）。\n步骤 3：乙霉威的氨基甲酸酯基由氨基与氯甲酸异丙酯（Cl—COO—CH(CH₃)₂）的取代反应引入，对应参照反应②。\n步骤 4：倒推：最后一步的反应物应为 3,4-二乙氧基苯胺（苯环上两个 —OC₂H₅ 与一个 —NH₂）。\n步骤 5：继续倒推：3,4-二乙氧基苯胺由硝基化合物还原得到，对应参照反应①；硝基化合物由原料硝化得到。\n步骤 6：原料 1,2-二乙氧基苯不含硝基，须先硝化引入硝基，再还原为氨基，最后取代。\n步骤 7：乙氧基为邻对位定位基，硝基进入乙氧基的对位（4-位），得 4-硝基-1,2-二乙氧基苯。\n步骤 8：路线：1,2-二乙氧基苯 → 4-硝基-1,2-二乙氧基苯 → 3,4-二乙氧基苯胺 → 乙霉威。\n步骤 9：各步试剂：硝化用浓 HNO₃/浓 H₂SO₄；还原用 Fe 粉/盐酸（参照反应①）；取代用氯甲酸异丙酯/吡啶（参照反应②）。\n步骤 10：官能团衔接：无硝基 → 有硝基 → 硝基变氨基 → 氨基变氨基甲酸酯基，无断档。\n步骤 11：乙霉威的两个乙氧基来自原料，氨基甲酸酯基来自氯甲酸异丙酯，来源齐全。\n步骤 12：答案：1,2-二乙氧基苯 —浓 HNO₃/浓 H₂SO₄→ 4-硝基-1,2-二乙氧基苯 —Fe 粉/盐酸→ 3,4-二乙氧基苯胺 —氯甲酸异丙酯/吡啶→ 乙霉威。",
  "file": "EX",
  "num": "15",
