  "example": "（2024 全国新课标卷 8 题）点击化学合成聚硫酸酯 W：双酚 A + SO₂F₂ —①→ 双氟磺酰基衍生物；双酚 A + (CH₃)₃SiCl —②→ 双三甲基硅醚；两者 —③ 催化剂→ W。下列说法正确的是____（B 项：AB 型单体 FSO₂—O—Ar—C(CH₃)₂—Ar—O—SiMe₃ 催化聚合也可生成 W）。\n步骤 1：双酚 A 与苯酚都含酚羟基，同属酚类。\n步骤 2：双酚 A 含两个酚羟基，苯酚含一个，官能团数目不同，不是同系物，A 错误。\n步骤 3：A 已排除，无需再比组成差值。\n步骤 4：反应③两单体缩合生成聚硫酸酯，同时生成小分子副产物，属缩聚反应。\n步骤 5：副产物由 FSO₂— 端脱下的 F 与 —OSiMe₃ 端脱下的 SiMe₃ 结合，为 Me₃SiF，不是六甲基二硅氧烷 (CH₃)₃Si—O—Si(CH₃)₃，C 错误。\n步骤 6：AB 型单体一端为 FSO₂—O—、另一端为 —O—SiMe₃，端基配对方式与 AA+BB 型相同，自聚所得重复单元 —O—SO₂—O—Ar—C(CH₃)₂—Ar— 与 W 相同，B 正确。\n步骤 7：W 主链含 S—O 键（硫酸酯键），碱性条件下易水解，比聚苯乙烯更易降解，D 错误。\n步骤 8：只有 B 正确，答案为 B。",
