  "example": "（2024 全国新课标卷 27 题(1)）湿法炼锌废渣“酸浸”前需粉碎处理，目的是____。（2024 全国新课标卷 28 题(3)）合成吡咯 X 时“搅拌”的作用是____。\n步骤 1：粉碎对象是废渣固体；搅拌对象是己-2,5-二酮与 4-甲氧基苯胺的反应混合物。\n步骤 2：粉碎使废渣颗粒变小、总表面积增大；搅拌使两种反应物充分混合接触。\n步骤 3：接触面积增大，酸浸速率加快；混合更充分，反应速率加快。\n步骤 4：酸浸速率加快，可提高浸出率；搅拌还可使受热均匀。\n步骤 5：粉碎目的：增大接触面积、加快酸浸速率（提高浸出率）；搅拌作用：使反应物充分混合（接触）、加快反应速率（受热均匀）。\n步骤 6：粉碎答接触面积、搅拌答充分混合，对应无误。",
