  "example": "（2024 全国新课标卷 29 题(3)）Ni(s)+4CO(g)=Ni(CO)₄(g)，总压 1.0 MPa（p3）、100℃ 时 Ni(CO)₄ 体积分数 x=0.90。CO 的平衡转化率 α=____，该温度下 Kp=____ (MPa)⁻³。\n步骤 1：方程式 Ni(s)+4CO(g)=Ni(CO)₄(g)，Ni(s) 为纯固体，不写入 Kp 表达式。\n步骤 2：p3、100℃ 时 x[Ni(CO)₄]=0.90。\n步骤 3：设 CO 起始 4 mol，转化 4α mol。\n步骤 4：三段式：平衡时 n(Ni(CO)₄)=α mol，n(CO)=4−4α mol，总物质的量 = 4−3α mol。\n步骤 5：x = α/(4−3α) = 0.90，解得 α = 36/37 ≈ 97.3%。\n步骤 6：p(Ni(CO)₄) = 1.0×0.90 = 0.90 MPa，p(CO) = 1.0×0.10 = 0.10 MPa。\n步骤 7：Kp = p(Ni(CO)₄)/p⁴(CO)。\n步骤 8：Kp = 0.90/(0.10)⁴ = 9000 (MPa)⁻³。\n步骤 9：α=97.3% 在 0–100% 之间，Kp 为正值；分压之和 0.90+0.10=1.0 MPa，等于总压。",
