  "example": "（2023 全国新课标卷 13 题改编）比较 B、C、O、N 基态原子的未成对电子数。\n步骤 1：价层排布：B 2s²2p¹、C 2s²2p²、N 2s²2p³、O 2s²2p⁴。\n步骤 2：按洪特规则，p 能级 3 个轨道优先单占：B 的 1 个 p 电子占 1 个轨道；C 的 2 个 p 电子各占 1 个轨道；N 的 3 个 p 电子各占 1 个轨道；O 的 4 个 p 电子中 3 个各占 1 个轨道、第 4 个与其中一个配对。\n步骤 3：未成对电子数：B 1、C 2、N 3、O 2。\n步骤 4：B<C=O<N。\n步骤 5：N 为 2p³ 半满，未成对电子数 3 等于轨道数，正确；O 的 2p⁴ 超过半满，配对后剩 2 个，正确。",
