  "example": "（2023 全国新课标卷 27 题(5)）安息香制备二苯乙二酮在乙酸体系中进行，乙酸除作溶剂外，另一主要作用是防止什么？\n步骤 1：FeCl₃ 电离出 Fe³⁺（弱碱 Fe(OH)₃ 的阳离子）与 Cl⁻（强酸根）。\n步骤 2：Fe³⁺ 水解：Fe³⁺+3H₂O⇌Fe(OH)₃+3H⁺。\n步骤 4：乙酸提供酸性环境，增大的 c(H⁺) 使水解平衡逆向移动，抑制 Fe³⁺ 水解。\n步骤 5：乙酸的另一主要作用是防止 FeCl₃ 水解。",
  "file": "EX",
