   "判断口诀：有弱才水解，无弱不水解；越弱越水解；谁强显谁性（强酸弱碱盐显酸性，强碱弱酸盐显碱性）。",
   "Fe³⁺ 水解：Fe³⁺+3H₂O⇌Fe(OH)₃+3H⁺，溶液显酸性；水解程度随温度升高而增大。",
