  "example": "（2021全国甲卷27题（4）（5））胆矾结晶水测定：\n步骤1：胆矾质量 m₂−m₁，失水质量 m₂−m₃，剩余 CuSO₄ 质量 m₃−m₁。\n步骤2：n(H₂O)=(m₂−m₃)/18，n(CuSO₄)=(m₃−m₁)/160。\n步骤3：x=160(m₂−m₃)/[18(m₃−m₁)]。\n步骤4：①胆矾未充分干燥：附着水计入失水量，(m₂−m₃) 偏大，偏高；②坩埚未置于干燥器中冷却：无水 CuSO₄ 吸水，m₃ 偏大，(m₂−m₃) 偏小，偏低；③胆矾迸溅：损失质量当作失水，(m₂−m₃) 偏大，偏高。故选①③。",
